public static void check(Solution solution) {
    assert Arrays.equals(solution.peopleIndexes(new int[]{{"leetcode"},{"google"},{"facebook"},{"amazon"}}), new int[]{0, 1, 2, 3});
    assert Arrays.equals(solution.peopleIndexes(new int[]{{"apple"},{"apple","google"},{"google","facebook"},{"apple","facebook","google"}}), new int[]{3});
    assert Arrays.equals(solution.peopleIndexes(new int[]{{"tech","innovation"},{"startup","tech"},{"innovation","startup","tech"}}), new int[]{2});
    assert Arrays.equals(solution.peopleIndexes(new int[]{{"leetcode","google","facebook"},{"leetcode","amazon"},{"facebook","google"}}), new int[]{0, 1});
    assert Arrays.equals(solution.peopleIndexes(new int[]{{"apple"},{"apple","google"},{"google","facebook"},{"facebook","microsoft"}}), new int[]{1, 2, 3});
    assert Arrays.equals(solution.peopleIndexes(new int[]{{"leetcode","google","facebook"},{"google","microsoft"},{"google","facebook"},{"google"},{"amazon"}}), new int[]{0, 1, 4});
    assert Arrays.equals(solution.peopleIndexes(new int[]{{"apple","microsoft"},{"google"},{"apple","google","microsoft"},{"google","microsoft"}}), new int[]{2});
    assert Arrays.equals(solution.peopleIndexes(new int[]{{"apple","banana","cherry"},{"banana","cherry"},{"banana"},{"apple","banana"}}), new int[]{0});
    assert Arrays.equals(solution.peopleIndexes(new int[]{{"apple","banana"},{"banana"},{"apple","orange"},{"banana","orange"},{"apple"}}), new int[]{0, 2, 3});
    assert Arrays.equals(solution.peopleIndexes(new int[]{{"apple"},{"banana"},{"cherry"},{"date"},{"elderberry"}}), new int[]{0, 1, 2, 3, 4});
    assert Arrays.equals(solution.peopleIndexes(new int[]{{"apple","google"},{"google"},{"apple","microsoft"},{"facebook"}}), new int[]{0, 2, 3});
