function check(candidate) {
    console.assert(JSON.stringify(candidate([["leetcode"],["google"],["facebook"],["amazon"]])) === JSON.stringify([0, 1, 2, 3]));
    console.assert(JSON.stringify(candidate([["apple"],["apple","google"],["google","facebook"],["apple","facebook","google"]])) === JSON.stringify([3]));
    console.assert(JSON.stringify(candidate([["tech","innovation"],["startup","tech"],["innovation","startup","tech"]])) === JSON.stringify([2]));
    console.assert(JSON.stringify(candidate([["leetcode","google","facebook"],["leetcode","amazon"],["facebook","google"]])) === JSON.stringify([0, 1]));
    console.assert(JSON.stringify(candidate([["apple"],["apple","google"],["google","facebook"],["facebook","microsoft"]])) === JSON.stringify([1, 2, 3]));
    console.assert(JSON.stringify(candidate([["leetcode","google","facebook"],["google","microsoft"],["google","facebook"],["google"],["amazon"]])) === JSON.stringify([0, 1, 4]));
    console.assert(JSON.stringify(candidate([["apple","microsoft"],["google"],["apple","google","microsoft"],["google","microsoft"]])) === JSON.stringify([2]));
    console.assert(JSON.stringify(candidate([["apple","banana","cherry"],["banana","cherry"],["banana"],["apple","banana"]])) === JSON.stringify([0]));
    console.assert(JSON.stringify(candidate([["apple","banana"],["banana"],["apple","orange"],["banana","orange"],["apple"]])) === JSON.stringify([0, 2, 3]));
    console.assert(JSON.stringify(candidate([["apple"],["banana"],["cherry"],["date"],["elderberry"]])) === JSON.stringify([0, 1, 2, 3, 4]));
    console.assert(JSON.stringify(candidate([["apple","google"],["google"],["apple","microsoft"],["facebook"]])) === JSON.stringify([0, 2, 3]));
    console.assert(JSON.stringify(candidate([["apple","banana"],["banana","cherry","date"],["apple","cherry","date"],["banana","date"],["apple","banana","cherry"]])) === JSON.stringify([1, 2, 4]));
    console.assert(JSON.stringify(candidate([["apple","banana","cherry"],["banana","cherry","date"],["apple","cherry","date","fig"],["banana","date","fig","grape"],["apple","banana","cherry","date","fig","grape","kiwi"]])) === JSON.stringify([4]));
    console.assert(JSON.stringify(candidate([["google","amazon","facebook"],["google","facebook"],["facebook"],["google"],["amazon"],["google","amazon"],["amazon","facebook"],["google","amazon","facebook"]])) === JSON.stringify([]));
    console.assert(JSON.stringify(candidate([["amazon","apple","facebook","google","microsoft"],["google"],["amazon","facebook"],["apple","google","microsoft"],["amazon","google","microsoft","apple","facebook"]])) === JSON.stringify([]));
